<?php require_once '../config/db.php';require_once '../includes/auth.php';require_role('admin');$msg='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['add_subject'])){$name=trim($_POST['name']);$course=trim($_POST['course']);$year=trim($_POST['year']);$sem=trim($_POST['semester']);if($name&&$course&&$year&&$sem){$pdo->prepare("INSERT INTO subjects(name,course,year,semester) VALUES(?,?,?,?)")->execute([$name,$course,$year,$sem]);$msg='Subject added.';}else$error='Fill all subject fields.';}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['add_unit'])){$sid=(int)$_POST['subject_id'];$no=(int)$_POST['unit_no'];$name=trim($_POST['unit_name']);if($sid&&$no&&$name){$pdo->prepare("INSERT INTO units(subject_id,unit_no,unit_name) VALUES(?,?,?)")->execute([$sid,$no,$name]);$msg='Unit added.';}}
$subjects=$pdo->query("SELECT * FROM subjects ORDER BY name")->fetchAll();$units=$pdo->query("SELECT u.*,s.name subject_name FROM units u JOIN subjects s ON s.id=u.subject_id ORDER BY s.name,u.unit_no")->fetchAll();
$page_title='Subjects';$css_path='../assets/css/style.css';$home_path='dashboard.php';$logout_path='../logout.php';$role='admin';include '../includes/header.php';?><div class="layout"><?php include '../includes/sidebar.php';?><h1 class="page-title">Subjects & Units</h1><?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<div class="form-row"><div class="form-card"><h3>Add Subject</h3><form method="post"><input type="hidden" name="add_subject" value="1"><label>Subject Name</label><input name="name" placeholder="Web Technologies" required><label>Course</label><input name="course" value="MCA" required><label>Year</label><input name="year" value="1st Year" required><label>Semester</label><input name="semester" value="1st Semester" required><button class="btn primary">Add Subject</button></form></div>
<div class="form-card"><h3>Add Unit</h3><form method="post"><input type="hidden" name="add_unit" value="1"><label>Subject</label><select name="subject_id" required><?php foreach($subjects as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select><label>Unit Number</label><input type="number" name="unit_no" min="1" required><label>Unit Name</label><input name="unit_name" required><button class="btn green">Add Unit</button></form></div></div>
<div class="table-card recent"><h3>Units</h3><table><thead><tr><th>Subject</th><th>Unit</th><th>Name</th></tr></thead><tbody><?php foreach($units as $u):?><tr><td><?=e($u['subject_name'])?></td><td>Unit <?=$u['unit_no']?></td><td><?=e($u['unit_name'])?></td></tr><?php endforeach;?></tbody></table></div></main></div><?php include '../includes/footer.php';?>